(function(){
const packages=window.OwnedOfficePackages;
window.OwnedOfficePackages=packages;let selected=packages[0];const money=n=>'$'+n.toLocaleString('en-US');const form=document.querySelector('#brief-form');
function render(){const office=document.querySelector('#owned-name').value.trim()||'Your company’s digital office';const character=document.querySelector('#owned-character').value.trim()||'To be chosen';const style=document.querySelector('#owned-style').value;document.querySelector('#owned-summary').innerHTML=`<h3>${selected.name}</h3><p class="office-total">${money(selected.price)}<small> / one-time build, proposed</small></p><div class="weekly-price">4 × <b>${money(selected.price/4)}</b><span>at agreed project milestones</span></div><p>${selected.scope}</p><p>${selected.delivery}</p><p class="fine">A standard connection uses an available documented API and authorized access. Feasibility is checked before quoting. Bespoke systems, migrations and custom integrations may change the scope and price.</p>`;window.ownedOfficeSelection={text:`PROPOSED COMPANY-OWNED OFFICE BUILD\nOffice name: ${office}\nLead character: ${character}\nCharacter style: ${style}\nStarting scope: ${selected.name}\nBuild estimate: ${money(selected.price)} one time\nMilestone payments: 4 x ${money(selected.price/4)} (scope/kickoff, prototype approval, integration testing, acceptance/handover)\nScope: ${selected.scope}\nDeliverables: ${selected.delivery}\nOngoing costs: API usage, hosting, domains and required third-party services. Optional maintenance is separate.\nHandover: agreed source, deployment configuration, documentation, admin access and training; ownership and third-party rights are defined in the contract.\nSupport: written defect-fix period; subsequent maintenance, provider changes and enhancements scoped separately. No lifetime operation guarantee.\nNo order, payment or build has been created.`};}
packages.forEach((p,i)=>{const label=document.createElement('label');label.className='office-option';label.innerHTML=`<input type="radio" name="owned-package" value="${p.id}" ${i===0?'checked':''}><span><strong>${p.name}</strong><small>${p.scope}</small></span><b>${money(p.price)}<small>one-time, proposed</small></b>`;label.querySelector('input').onchange=()=>{selected=p;render()};document.querySelector('#owned-packages').append(label)});
['#owned-name','#owned-character','#owned-style'].forEach(s=>document.querySelector(s).addEventListener('input',render));
function syncRoute(){const owned=form.elements.serviceRoute.value==='owned';form.elements.goal.placeholder=owned?'Your departments, workflows, preferred systems and build goals':'Your priority, deadline, or an example of the work you need';form.elements.relationship.replaceChildren();(owned?['Four milestone payments','Full build upfront','Help me decide']:['Four weekly payments','Full 28-day cycle upfront','Annual plan · four quarterly payments','Help me decide']).forEach(t=>{const o=document.createElement('option');o.textContent=t;form.elements.relationship.append(o)})}
form.elements.serviceRoute.addEventListener('change',syncRoute);
document.querySelector('#owned-start').onclick=()=>{render();openAssessment();form.elements.serviceRoute.value='owned';syncRoute();form.elements.goal.placeholder='Your company’s departments, workflows, preferred systems and build goals'};
render();syncRoute();
})();
